        RawDua(23, "اللَّهُمَّ لَا تَدَعْ لِي ذَنْبًا إِلَّا غَفَرْتَهُ، وَلَا هَمًّا إِلَّا فَرَّجْتَهُ، وَلَا حَاجَةً هِيَ لَكَ رِضًا إِلَّا قَضَيْتَهَا، يَا أَرْحَمَ الرَّاحِمِينَ.", "الترمذي (482)", AuthenticityGrade.NEEDS_REVIEW, LengthCategory.MEDIUM, CAT_COMPREHENSIVE, note = "صرّح مؤلف \"مفاتيح الدعاء\" بأن في إسناده مقالاً (ضعفاً في السند)؛ يحتاج مراجعة شرعية قبل اعتماده.", needsReview = true),
        RawDua(24, "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى.", "مسلم (2721)، الترمذي (3795)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_COMPREHENSIVE),
        RawDua(25, "اللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ مِنَ النَّارِ.", "الحاكم (1946)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_COMPREHENSIVE),
        RawDua(26, "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ؛ فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ.", "الطبراني (10379)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_COMPREHENSIVE),
        RawDua(27, "اللَّهُمَّ زِدْنَا وَلَا تُنْقِصْنَا، وَأَكْرِمْنَا وَلَا تُهِنَّا، وَأَعْطِنَا وَلَا تَحْرِمْنَا، وَآثِرْنَا وَلَا تُؤْثِرْ عَلَيْنَا، وَأَرْضِنَا وَارْضَ عَنَّا.", "الترمذي (3446)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_COMPREHENSIVE),
        RawDua(28, "اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ، وَخَيْرَ الدُّعَاءِ، وَخَيْرَ النَّجَاحِ، وَخَيْرَ الْعَمَلِ، وَخَيْرَ الثَّوَابِ، وَخَيْرَ الْحَيَاةِ، وَخَيْرَ الْمَمَاتِ، وَثَبِّتْنِي وَثَقِّلْ مَوَازِينِي، وَحَقِّقْ إِيمَانِي، وَارْفَعْ دَرَجَتِي، وَتَقَبَّلْ صَلَاتِي، وَاغْفِرْ خَطِيئَتِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمين، اللَّهُمَّ إِنِّي أَسْأَلُكَ فَوَاتِحَ الْخَيْرِ وَخَوَاتِمَهُ وَجَوَامِعَهُ وَأَوَّلَهُ وَآخِرَهُ وَظَاهِرَهُ وَبَاطِنَهُ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تَرْفَعَ ذِكْرِي، وَتَضَعَ وِزْرِي، وَتُصْلِحَ أَمْرِي، وَتُطَهِّرَ قَلْبِي، وَتُحَصِّنَ فَرْجِي، وَتُنَوِّرَ لِي قَلْبِي، وَتَغْفِرَ لِي ذَنْبِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، آمين، اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تُبَارِكَ لِي فِي نَفْسِي، وَفِي سَمْعِي، وَفِي بَصَرِي، وَفِي رُوحِي، وَفِي خُلُقِي، وَفِي أَهْلِي، وَمَحْيَايَ، وَمَمَاتِي، وَفِي عَمَلِي، وَتَقَبَّلْ حَسَنَاتِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ.", "الحاكم (1932)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_COMPREHENSIVE),
        RawDua(29, "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ.", "البقرة: 201", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_COMPREHENSIVE, popular = true),

        // الدعاء للأهل والذرية والوالدين (30-41)
        RawDua(30, "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي، وَوَسِّعْ لِي فِي دَارِي، وَبَارِكْ لِي فِيمَا رَزَقْتَنِي.", "الترمذي (3808)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_FAMILY),
        RawDua(31, "اللَّهُمَّ أَكْثِرْ مَالِي وَوَلَدِي، وَبَارِكْ لِي فِيمَا أَعْطَيْتَنِي.", "البخاري، من حديث أنس بن مالك", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_FAMILY, narrator = "أنس بن مالك رضي الله عنه"),
        RawDua(32, "رَبِّ أَنْزِلْنِي مُنْزَلًا مُبَارَكًا وَأَنْتَ خَيْرُ الْمُنْزِلِينَ.", "المؤمنون: 29", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_FAMILY),
        RawDua(33, "رَبِّ هَبْ لِي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ.", "آل عمران: 38", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_FAMILY),
        RawDua(34, "رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ.", "الصافات: 100", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_FAMILY),
        RawDua(35, "رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنْتَ خَيْرُ الْوَارِثِينَ.", "الأنبياء: 89", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_FAMILY),
        RawDua(36, "رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا، اللَّهُمَّ اجْعَلْنِي مِنْ أَئِمَّةِ الْمُتَّقِينَ.", "الفرقان: 74؛ والزيادة الأخيرة من موطأ مالك (42)", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_FAMILY, note = "الآية من سورة الفرقان، والجملة الأخيرة زيادة من موطأ الإمام مالك."),
        RawDua(37, "رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ، رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ.", "إبراهيم: 40-41", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_FAMILY),
        RawDua(38, "رَبِّ اجْعَلْ هَذَا الْبَلَدَ آمِنًا وَاجْنُبْنِي وَبَنِيَّ أَنْ نَعْبُدَ الْأَصْنَامَ.", "إبراهيم: 35", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_FAMILY),
        RawDua(39, "رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي، إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ.", "الأحقاف: 15", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_FAMILY),
        RawDua(40, "رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ.", "نوح: 28", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_FAMILY),
        RawDua(41, "رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا.", "الإسراء: 24", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_FAMILY, popular = true),

        // سؤال الله الرزق وقضاء الدين (42-50)
        RawDua(42, "اللَّهُمَّ رَبَّ السَّمَاوَاتِ وَرَبَّ الْأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ.", "مسلم (2713)", AuthenticityGrade.SAHIH, LengthCategory.LONG, CAT_PROVISION),
        RawDua(43, "اللَّهُمَّ فَالِقَ الْإِصْبَاحِ، وَجَاعِلَ اللَّيْلِ سَكَنًا، وَالشَّمْسَ وَالْقَمَرَ حُسْبَانًا، اقْضِ عَنِّي الدَّيْنَ، وَأَغْنِنِي مِنَ الْفَقْرِ، وَأَمْتِعْنِي بِسَمْعِي وَبَصَرِي وَقُوَّتِي فِي سَبِيلِكَ.", "موطأ مالك (27)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_PROVISION),
        RawDua(44, "قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَتَرْزُقُ مَنْ تَشَاءُ بِغَيْرِ حِسَابٍ.", "آل عمران: 26-27", AuthenticityGrade.QURAN, LengthCategory.LONG, CAT_PROVISION),
        RawDua(45, "اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ.", "الترمذي (3563)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_PROVISION),
        RawDua(46, "اللَّهُمَّ قَنِّعْنِي بِمَا رَزَقْتَنِي، وَبَارِكْ لِي فِيهِ، وَاخْلُفْ عَلَيَّ كُلَّ غَائِبَةٍ لِي بِخَيْرٍ.", "الحاكم (1899)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_PROVISION),
        RawDua(47, "اللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ عِنْدَ كِبَرِ سِنِّي، وَانْقِطَاعِ عُمُرِي.", "الحاكم (2010)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_PROVISION),
        RawDua(48, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ، وَالْقِلَّةِ، وَالذِّلَّةِ، وَأَعُوذُ بِكَ مِنْ أَنْ أَظْلِمَ أَوْ أُظْلَمَ.", "أبو داود (1544)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_PROVISION),
        RawDua(49, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ، فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ، فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ.", "أبو داود (1547)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_PROVISION),
        RawDua(50, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ.", "أبو داود (5090)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_PROVISION),

        // الدعاء عند الهم والكرب (51-57)
        RawDua(51, "اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ.", "أبو داود (5090)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_DISTRESS),
        RawDua(52, "يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ، أَصْلِحْ لِي شَأْنِي كُلَّهُ، وَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ.", "الحاكم (2023)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_DISTRESS, popular = true),
        RawDua(53, "لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ.", "البخاري (6346)، مسلم (2730)", AuthenticityGrade.SAHIH, LengthCategory.MEDIUM, CAT_DISTRESS, popular = true),
        RawDua(54, "اللَّهُمَّ فَارِجَ الْهَمِّ، كَاشِفَ الْغَمِّ، مُجِيبَ دَعْوَةِ الْمُضْطَرِّينَ، رَحْمَنَ الدُّنْيَا وَالْآخِرَةِ وَرَحِيمَهُمَا، أَنْتَ تَرْحَمُنِي فَارْحَمْنِي بِرَحْمَةٍ تُغْنِينِي بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ.", "الحاكم (1919)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_DISTRESS),
        RawDua(55, "اللَّهُمَّ إِنِّي عَبْدُكَ، وَابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي.", "أحمد / الحاكم (رقم التخريج الدقيق لم يتضح بثقة كافية في الصفحة)", AuthenticityGrade.NEEDS_REVIEW, LengthCategory.LONG, CAT_DISTRESS, note = "دعاء ابن مسعود المشهور عند الهمّ؛ لم أتمكن من تأكيد رقم التخريج بثقة من الصفحة، يُرجى تأكيده من النسخة الأصلية قبل النشر.", needsReview = true),
        RawDua(56, "اللَّهُمَّ إِنِّي ضَعِيفٌ فَقَوِّ فِي رِضَاكَ ضَعْفِي، وَخُذْ إِلَى الْخَيْرِ بِنَاصِيَتِي، وَاجْعَلِ الْإِسْلَامَ مُنْتَهَى رِضَائِي، اللَّهُمَّ إِنِّي ضَعِيفٌ فَقَوِّنِي، وَإِنِّي ذَلِيلٌ فَأَعِزَّنِي، وَإِنِّي فَقِيرٌ فَارْزُقْنِي.", "أحمد (4318)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_DISTRESS),
        RawDua(57, "رَبِّ إِنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ.", "الأنبياء: 83", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_DISTRESS),

        // التوكل على الله والإنابة إليه (58-61)
        RawDua(58, "اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، اللَّهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ لَا إِلَهَ إِلَّا أَنْتَ أَنْ تُضِلَّنِي، أَنْتَ الْحَيُّ الَّذِي لَا يَمُوتُ، وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ.", "مسلم (2717)", AuthenticityGrade.SAHIH, LengthCategory.LONG, CAT_TAWAKKUL),
        RawDua(60, "وَأُفَوِّضُ أَمْرِي إِلَى اللهِ إِنَّ اللهَ بَصِيرٌ بِالْعِبَادِ.", "غافر: 44", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_TAWAKKUL),
        RawDua(61, "عَلَى اللهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِلْقَوْمِ الظَّالِمِينَ، وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ.", "يونس: 85-86", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_TAWAKKUL),

        // سؤال الله الهداية والسداد (62-69)
        RawDua(62, "رَبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ، رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ.", "الممتحنة: 4-5", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_GUIDANCE),
        RawDua(63, "رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الْهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مُطِيعًا، إِلَيْكَ مُخْبِتًا، إِلَيْكَ أَوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَاهْدِ قَلْبِي، وَسَدِّدْ لِسَانِي، وَثَبِّتْ حُجَّتِي، وَاسْلُلْ سَخِيمَةَ قَلْبِي.", "أبو داود (1510)، الترمذي (3551)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_GUIDANCE),
        RawDua(64, "رَبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَلْ لِي مِنْ لَدُنْكَ سُلْطَانًا نَصِيرًا.", "الإسراء: 80", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_GUIDANCE),
        RawDua(65, "اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي.", "مسلم (2725)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_GUIDANCE, popular = true),
        RawDua(66, "اللَّهُمَّ رَبَّ جِبْرَائِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ أَنْتَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ.", "مسلم (770)", AuthenticityGrade.SAHIH, LengthCategory.LONG, CAT_GUIDANCE),
        RawDua(67, "اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ، فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.", "النسائي (1746)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_GUIDANCE, note = "دعاء القنوت؛ $HASAN_NOTE"),
        RawDua(68, "اللَّهُمَّ أَلْهِمْنِي رُشْدِي، وَأَعِذْنِي مِنْ شَرِّ نَفْسِي.", "الترمذي (3788)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_GUIDANCE),
        RawDua(69, "اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَأَسْأَلُكَ حُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَأَسْأَلُكَ لِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ.", "أحمد (17114)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_GUIDANCE),

        // صلاح القلب والثبات على الدين (70-80)
        RawDua(70, "رَبَّنَا آتِنَا مِنْ لَدُنْكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا.", "الكهف: 10", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_GUIDANCE),
        RawDua(71, "يَا مُقَلِّبَ الْقُلُوبِ، ثَبِّتْ قَلْبِي عَلَى دِينِكَ.", "الترمذي (3831)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_GUIDANCE, popular = true),
        RawDua(72, "اللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ.", "مسلم (2654)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_GUIDANCE),
        RawDua(73, "اللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ.", "مسلم (2720)", AuthenticityGrade.SAHIH, LengthCategory.MEDIUM, CAT_GUIDANCE),
        RawDua(74, "اللَّهُمَّ أَعِنَّا عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ.", "الحاكم (1859)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_GUIDANCE),
        RawDua(75, "اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُولُ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ الْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيبَاتِ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الْوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا.", "الترمذي (3809)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_GUIDANCE),
        RawDua(76, "اللَّهُمَّ ارْزُقْنِي حُبَّكَ، وَحُبَّ مَنْ يَنْفَعُنِي حُبُّهُ عِنْدَكَ، اللَّهُمَّ مَا رَزَقْتَنِي مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُحِبُّ.", "الترمذي (3797)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_GUIDANCE),
        RawDua(77, "اللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ، وَتَرْكَ الْمُنْكَرَاتِ، وَحُبَّ الْمَسَاكِينِ، وَإِذَا أَرَدْتَ بِالنَّاسِ فِتْنَةً فَاقْبِضْنِي إِلَيْكَ غَيْرَ مَفْتُونٍ.", "موطأ مالك (40)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_GUIDANCE),
        RawDua(78, "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ مِنْ خَلْفِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَاجْعَلْ مِنْ فَوْقِي نُورًا وَمِنْ تَحْتِي نُورًا، اللَّهُمَّ أَعْطِنِي نُورًا.", "مسلم (763)", AuthenticityGrade.SAHIH, LengthCategory.LONG, CAT_GUIDANCE),
        RawDua(79, "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ.", "آل عمران: 8", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_GUIDANCE, popular = true),
        RawDua(80, "اللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا، وَأَصْلِحْ ذَاتَ بَيْنِنَا، وَاهْدِنَا سُبُلَ السَّلَامِ، وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ، وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ، وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا، وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ، وَاجْعَلْنَا شَاكِرِينَ لِنِعْمَتِكَ، مُثْنِينَ بِهَا قَابِلِيهَا، وَأَتِمَّهَا عَلَيْنَا.", "أبو داود (969)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_GUIDANCE),

        // سؤال الله العلم النافع (81-83)
        RawDua(81, "رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ.", "الحشر: 10", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_KNOWLEDGE),
        RawDua(82, "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا.", "أحمد (26602)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_KNOWLEDGE),
        RawDua(83, "اللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي، وَعَلِّمْنِي مَا يَنْفَعُنِي، وَزِدْنِي عِلْمًا، الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، وَأَعُوذُ بِاللَّهِ مِنْ حَالِ أَهْلِ النَّارِ.", "الترمذي (3599)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_KNOWLEDGE),

        // سؤال الله حسن الخلق (84-86)
        RawDua(84, "رَبِّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي، يَفْقَهُوا قَوْلِي.", "طه: 25-28", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_CHARACTER),
        RawDua(85, "اللَّهُمَّ اغْفِرْ لِي خَطَايَايَ وَذُنُوبِي كُلَّهَا، اللَّهُمَّ انْعَشْنِي وَأَحْيِنِي وَارْزُقْنِي وَاهْدِنِي لِصَالِحِ الْأَعْمَالِ وَالْأَخْلَاقِ، إِنَّهُ لَا يَهْدِي لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ.", "الحاكم (6055)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_CHARACTER),
        RawDua(86, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ، وَالْأَعْمَالِ، وَالْأَهْوَاءِ.", "الترمذي (3908)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_CHARACTER),

        // سؤال الله العافية والحفظ (87-91)
        RawDua(87, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الشِّقَاقِ، وَالنِّفَاقِ، وَسُوءِ الْأَخْلَاقِ.", "أبو داود (1546)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_WELLBEING),
        RawDua(88, "اللَّهُمَّ عَافِنِي فِي جَسَدِي، وَعَافِنِي فِي بَصَرِي، وَاجْعَلْهُ الْوَارِثَ مِنِّي.", "الترمذي", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_WELLBEING, note = "$HASAN_NOTE رقم الحديث الدقيق لم يتضح بثقة كافية من الصفحة، يُرجى تأكيده."),
        RawDua(89, "اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.", "ابن ماجه (3871)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_WELLBEING),
        RawDua(90, "اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الْأَرَضِينَ وَمَا أَقْلَلْنَ، وَرَبَّ الشَّيَاطِينِ وَمَا أَضْلَلْنَ، كُنْ لِي جَارًا مِنْ شَرِّ خَلْقِكَ كُلِّهِمْ جَمِيعًا، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ أَنْ يَبْغِيَ، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلَهَ غَيْرُكَ.", "الحاكم (1923)، الترمذي (3832)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_WELLBEING),
        RawDua(91, "اللَّهُمَّ احْفَظْنِي بِالْإِسْلَامِ قَائِمًا، وَاحْفَظْنِي بِالْإِسْلَامِ قَاعِدًا، وَاحْفَظْنِي بِالْإِسْلَامِ رَاقِدًا، وَلَا تُشْمِتْ بِيَ عَدُوًّا حَاسِدًا، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ، وَأَعُوذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ.", "الحاكم (1945)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_WELLBEING),

        // الاستعاذة بالله من الشرور (92-110)
        RawDua(92, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ.", "أبو داود (5094)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_PROTECTION),
        RawDua(93, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي.", "أبو داود (1551)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_PROTECTION),
        RawDua(94, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ.", "مسلم (2716)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_PROTECTION),
        RawDua(95, "اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ.", "مسلم (486)", AuthenticityGrade.SAHIH, LengthCategory.MEDIUM, CAT_PROTECTION),
        RawDua(96, "اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ.", "الترمذي", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_PROTECTION, note = "$HASAN_NOTE رقم الحديث الدقيق لم يتضح بثقة كافية من الصفحة، يُرجى تأكيده."),
        RawDua(97, "رَبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَحْضُرُونِ.", "المؤمنون: 97-98", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_PROTECTION),
        RawDua(98, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ، وَدَرَكِ الشَّقَاءِ، وَسُوءِ الْقَضَاءِ، وَشَمَاتَةِ الْأَعْدَاءِ.", "البخاري (6347)، مسلم (2707)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_PROTECTION),
        RawDua(99, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ.", "مسلم (2739)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_PROTECTION),
        RawDua(100, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَدْمِ، وَأَعُوذُ بِكَ مِنَ التَّرَدِّي، وَأَعُوذُ بِكَ مِنَ الْغَرَقِ، وَالْحَرَقِ، وَالْهَرَمِ، وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِيَ الشَّيْطَانُ عِنْدَ الْمَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا.", "أبو داود (1552)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_PROTECTION),
        RawDua(101, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ تَخَبَّطَنِي الشَّيْطَانُ عَلَى غِرَّةٍ، أَوْ تُدْرِكَنِي فِي غَفْلَةٍ، أَوْ تَجْعَلَنِي مِنَ الْغَافِلِينَ.", "مصنف ابن أبي شيبة (29517)", AuthenticityGrade.NEEDS_REVIEW, LengthCategory.MEDIUM, CAT_PROTECTION, note = "أثر موقوف على عمر بن الخطاب رضي الله عنه من دعائه، وليس حديثاً مرفوعاً إلى النبي ﷺ كما نص عليه المؤلف.", needsReview = true, narrator = "عمر بن الخطاب رضي الله عنه"),
        RawDua(102, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ السُّوءِ، وَمِنْ زَوْجٍ تُشَيِّبُنِي قَبْلَ الْمَشِيبِ، وَمِنْ وَلَدٍ يَكُونُ عَلَيَّ رَبًّا، وَمِنْ مَالٍ يَكُونُ عَلَيَّ عَذَابًا، وَمِنْ خَلِيلٍ مَاكِرٍ عَيْنُهُ تَرَانِي وَقَلْبُهُ يَرْعَانِي، إِنْ رَأَى حَسَنَةً دَفَنَهَا، وَإِذَا رَأَى سَيِّئَةً أَذَاعَهَا.", "الطبراني في الدعاء (1339)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_PROTECTION),
        RawDua(103, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ.", "البخاري (6369)", AuthenticityGrade.SAHIH, LengthCategory.MEDIUM, CAT_PROTECTION, popular = true),
        RawDua(104, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ، وَالْكَسَلِ، وَالْجُبْنِ، وَالْبُخْلِ، وَالْهَرَمِ، وَعَذَابِ الْقَبْرِ، اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا.", "مسلم (2722)", AuthenticityGrade.SAHIH, LengthCategory.LONG, CAT_PROTECTION),
        RawDua(105, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْقَسْوَةِ، وَالْغَفْلَةِ، وَالْعَيْلَةِ، وَالذِّلَّةِ، وَالْمَسْكَنَةِ، وَأَعُوذُ بِكَ مِنَ الْفَقْرِ وَالْكُفْرِ، وَالْفُسُوقِ وَالشِّقَاقِ وَالنِّفَاقِ وَالسُّمْعَةِ وَالرِّيَاءِ، وَأَعُوذُ بِكَ مِنَ الصَّمَمِ وَالْبَكَمِ وَالْجُنُونِ وَالْجُذَامِ وَالْبَرَصِ وَسَيِّئِ الْأَسْقَامِ.", "الحاكم (1965)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_PROTECTION),
        RawDua(106, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ، وَعَذَابِ النَّارِ، وَمِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ، وَمِنْ شَرِّ فِتْنَةِ الْغِنَى، وَأَعُوذُ بِكَ مِنْ شَرِّ فِتْنَةِ الْفَقْرِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ.", "البخاري (832)، مسلم (587)", AuthenticityGrade.SAHIH, LengthCategory.LONG, CAT_PROTECTION),
        RawDua(107, "اللَّهُمَّ اغْسِلْ خَطَايَايَ بِمَاءِ الثَّلْجِ وَالْبَرَدِ، وَنَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ.", "البخاري (832)، مسلم (587)", AuthenticityGrade.SAHIH, LengthCategory.MEDIUM, CAT_PROTECTION),
        RawDua(108, "اللَّهُمَّ رَبَّ جِبْرَائِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، أَعُوذُ بِكَ مِنْ حَرِّ النَّارِ وَمِنْ عَذَابِ الْقَبْرِ.", "مسلم (590)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_PROTECTION),
        RawDua(109, "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ.", "مسلم (590)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_PROTECTION),
        RawDua(110, "رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا.", "الفرقان: 65", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_PROTECTION),

        // الاستنصار بالله على الأعداء (111-115)
        RawDua(111, "اللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ، اللَّهُمَّ لَا مَانِعَ لِمَا بَسَطْتَ، وَلَا بَاسِطَ لِمَا قَبَضْتَ، وَلَا هَادِيَ لِمَنْ أَضْلَلْتَ، وَلَا مُضِلَّ لِمَنْ هَدَيْتَ، وَلَا مُنْطِيَ لِمَا مَنَعْتَ، وَلَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُقَرِّبَ لِمَا بَاعَدْتَ، وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ، اللَّهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ الْقِيَامَةِ، وَالْأَمْنَ يَوْمَ الْخَوْفِ، اللَّهُمَّ عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا، وَشَرِّ مَا مَنَعْتَنَا، اللَّهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا، وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ، وَاجْعَلْنَا مِنَ الرَّاشِدِينَ، اللَّهُمَّ تَوَفَّنَا مُسْلِمِينَ، وَأَحْيِنَا مُسْلِمِينَ، وَأَلْحِقْنَا بِالصَّالِحِينَ، غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ، اللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يُكَذِّبُونَ رُسُلَكَ، وَيَصُدُّونَ عَنْ سَبِيلِكَ، وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ، إِلَهَ الْحَقِّ.", "الحاكم (1889)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_VICTORY),
        RawDua(112, "اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الْأَحْزَابَ، اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ.", "البخاري (2933)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_VICTORY),
        RawDua(113, "اللَّهُمَّ إِنِّي أَجْعَلُكَ فِي نُحُورِهِمْ، وَأَعُوذُ بِكَ مِنْ شُرُورِهِمْ.", "أحمد (17719)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_VICTORY),
        RawDua(114, "رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.", "البقرة: 250", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_VICTORY),
        RawDua(115, "رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ.", "آل عمران: 147", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_VICTORY),

        // حسن الخاتمة والنجاة في الآخرة (116-125)
        RawDua(116, "اللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ.", "أحمد (17627)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_AFTERLIFE),
        RawDua(117, "اللَّهُمَّ اجْعَلْ خَيْرَ عُمُرِي آخِرَهُ، وَخَيْرَ عَمَلِي خَوَاتِمَهُ، وَخَيْرَ أَيَّامِي يَوْمَ أَلْقَاكَ.", "مصنف ابن أبي شيبة (29510)", AuthenticityGrade.NEEDS_REVIEW, LengthCategory.SHORT, CAT_AFTERLIFE, note = "أثر موقوف على أبي بكر الصديق رضي الله عنه من دعائه، وليس حديثاً مرفوعاً إلى النبي ﷺ كما نص عليه المؤلف.", needsReview = true, narrator = "أبو بكر الصديق رضي الله عنه"),
        RawDua(118, "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِيشَةً نَقِيَّةً، وَمِيتَةً سَوِيَّةً، وَمَرَدًّا غَيْرَ مُخْزٍ وَلَا فَاضِحٍ.", "الحاكم (2009)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_AFTERLIFE),
        RawDua(119, "اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ، وَقُدْرَتِكَ عَلَى الْخَلْقِ، أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ، فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ.", "النسائي (1305)", AuthenticityGrade.HASAN, LengthCategory.LONG, CAT_AFTERLIFE),
        RawDua(120, "اللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ، وَنَعِيمًا لَا يَنْفَدُ، وَمُرَافَقَةَ نَبِيِّكَ مُحَمَّدٍ ﷺ فِي أَعْلَى جَنَّةِ الْخُلْدِ.", "أحمد (4255)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_AFTERLIFE),
        RawDua(121, "رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ.", "مسلم (709)", AuthenticityGrade.SAHIH, LengthCategory.SHORT, CAT_AFTERLIFE),
        RawDua(122, "اللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا.", "أحمد (24214)", AuthenticityGrade.HASAN, LengthCategory.SHORT, CAT_AFTERLIFE),
        RawDua(123, "فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنْتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ.", "يوسف: 101", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_AFTERLIFE),
        RawDua(124, "رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ، وَاجْعَلْ لِي لِسَانَ صِدْقٍ فِي الْآخِرِينَ، وَاجْعَلْنِي مِنْ وَرَثَةِ جَنَّةِ النَّعِيمِ.", "الشعراء: 83-85", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_AFTERLIFE),
        RawDua(125, "وَلَا تُخْزِنِي يَوْمَ يُبْعَثُونَ، يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ، إِلَّا مَنْ أَتَى اللهَ بِقَلْبٍ سَلِيمٍ.", "الشعراء: 87-89", AuthenticityGrade.QURAN, LengthCategory.MEDIUM, CAT_AFTERLIFE),

        // ختم الدعاء بالحمد وسؤال القبول (126-130)
        RawDua(126, "الْحَمْدُ لِلَّهِ الَّذِي كَفَانِي وَآوَانِي، الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي وَسَقَانِي، الْحَمْدُ لِلَّهِ الَّذِي مَنَّ عَلَيَّ فَأَفْضَلَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ بِعِزَّتِكَ أَنْ تُنَجِّيَنِي مِنَ النَّارِ.", "الحاكم (2024)", AuthenticityGrade.HASAN, LengthCategory.MEDIUM, CAT_PRAISE),
        RawDua(127, "الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللهُ.", "الأعراف: 43", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_PRAISE),
        RawDua(128, "إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ.", "إبراهيم: 39", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_PRAISE),
        RawDua(129, "إِنَّ رَبِّي قَرِيبٌ مُجِيبٌ.", "هود: 61", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_PRAISE),
        RawDua(130, "رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ.", "البقرة: 127", AuthenticityGrade.QURAN, LengthCategory.SHORT, CAT_PRAISE, popular = true)
    )

    val adhkar: List<DhikrEntity> = raw
        .map { d ->
            DhikrEntity(
                id = 2000L + d.n,
                arabicText = d.text,
                source = "مفاتيح الدعاء (${d.source})",
                authenticityGrade = d.grade,
                authenticityNote = d.note ?: when (d.grade) {
                    AuthenticityGrade.HASAN -> HASAN_NOTE
                    else -> null
                },
                fullVirtue = null,
                narrationContext = "لم يرد سبب ورود موثق",
                chainOfNarration = null,
                narrator = d.narrator,
                repeatCount = null,
                englishTranslation = null,
                lengthCategory = d.length,
                needsReview = d.needsReview
            )
        }

    // ذكرا "سيد الاستغفار" و"حسبي الله..." موجودان أصلاً بالمعرّفين 5 و6 في SeedData؛
    // هنا فقط نربطهما بتصنيف المصدر الجديد بدل تكرار صفّيهما.
    private val extraCrossRefsForExistingDhikr = listOf(
        DhikrCategoryCrossRef(5L, CAT_SOURCE_MAFATIH),
        DhikrCategoryCrossRef(6L, CAT_SOURCE_MAFATIH)
    )

    val crossRefs: List<DhikrCategoryCrossRef> = buildList {
        addAll(extraCrossRefsForExistingDhikr)
        raw.forEach { d ->
            val dhikrId = 2000L + d.n
            add(DhikrCategoryCrossRef(dhikrId, CAT_SOURCE_MAFATIH))
            add(DhikrCategoryCrossRef(dhikrId, d.themeCategoryId))
            if (d.grade == AuthenticityGrade.QURAN) {
                add(DhikrCategoryCrossRef(dhikrId, CAT_SOURCE_QURAN))
            }
            if (d.popular) {
                add(DhikrCategoryCrossRef(dhikrId, CAT_POPULAR))
            }
        }
    }
}
